                }
/*------*/
                elseif($_SESSION['sc_session'][$this->Ini->sc_page]['grid_trprop_rsvp_r']['fast_search'][1] == 'eq')
                {
                    if(strcasecmp($_SESSION['sc_session'][$this->Ini->sc_page]['grid_trprop_rsvp_r']['fast_search'][2], $str_value) == 0)
