   $nm_saida->saida("   function NM_liga_tbody(tbody, Obj, Apl)\r\n");
   $nm_saida->saida("   {\r\n");
   $nm_saida->saida("      Nivel = parseInt (Obj[tbody].substr(3));\r\n");
   $nm_saida->saida("      for (ind = tbody + 1; ind < Obj.length; ind++)\r\n");
   $nm_saida->saida("      {\r\n");
   $nm_saida->saida("           Nv = parseInt (Obj[ind].substr(3));\r\n");
   $nm_saida->saida("           Tp = Obj[ind].substr(0, 3);\r\n");
   $nm_saida->saida("           if (Nivel == Nv && Tp == 'top')\r\n");
   $nm_saida->saida("           {\r\n");
   $nm_saida->saida("               break;\r\n");
   $nm_saida->saida("           }\r\n");
   $nm_saida->saida("           if (((Nivel + 1) == Nv && Tp == 'top') || (Nivel == Nv && Tp == 'bot'))\r\n");
   $nm_saida->saida("           {\r\n");
   $nm_saida->saida("               document.getElementById('tbody_' + Apl + '_' + ind + '_' + Tp).style.display='';\r\n");
   $nm_saida->saida("           } \r\n");
   $nm_saida->saida("      }\r\n");
   $nm_saida->saida("   }\r\n");
   $nm_saida->saida("   function NM_apaga_tbody(tbody, Obj, Apl)\r\n");
   $nm_saida->saida("   {\r\n");
   $nm_saida->saida("      Nivel = Obj[tbody].substr(3);\r\n");
   $nm_saida->saida("      for (ind = tbody + 1; ind < Obj.length; ind++)\r\n");
   $nm_saida->saida("      {\r\n");
   $nm_saida->saida("           Nv = Obj[ind].substr(3);\r\n");
   $nm_saida->saida("           Tp = Obj[ind].substr(0, 3);\r\n");
   $nm_saida->saida("           if ((Nivel == Nv && Tp == 'top') || Nv < Nivel)\r\n");
   $nm_saida->saida("           {\r\n");
   $nm_saida->saida("               break;\r\n");
   $nm_saida->saida("           }\r\n");
   $nm_saida->saida("           if ((Nivel != Nv) || (Nivel == Nv && Tp == 'bot'))\r\n");
   $nm_saida->saida("           {\r\n");
   $nm_saida->saida("               document.getElementById('tbody_' + Apl + '_' + ind + '_' + Tp).style.display='none';\r\n");
   $nm_saida->saida("               if (Tp == 'top')\r\n");
   $nm_saida->saida("               {\r\n");
   $nm_saida->saida("                   document.getElementById('b_open_' + Apl + '_' + ind).style.display='';\r\n");
   $nm_saida->saida("                   document.getElementById('b_close_' + Apl + '_' + ind).style.display='none';\r\n");
   $nm_saida->saida("               } \r\n");
   $nm_saida->saida("           } \r\n");
   $nm_saida->saida("      }\r\n");
   $nm_saida->saida("   }\r\n");
   $nm_saida->saida("    function showNestedGridLinks(objectName, timeoutIndex, anchorObject)\r\n");
   $nm_saida->saida("    {\r\n");
   $nm_saida->saida("        if (\"undefined\" != typeof timeoutIndex) {\r\n");
   $nm_saida->saida("            clearTimeout(timeoutIndex);\r\n");
   $nm_saida->saida("        }\r\n");
   $nm_saida->saida("        let thisObject = document.getElementById(objectName);\r\n");
   $nm_saida->saida("        thisObject.style.display = '';\r\n");
   $nm_saida->saida("        if (\"undefined\" != typeof anchorObject && \"null\" != typeof anchorObject) {\r\n");
   $nm_saida->saida("            positionNestedGridLinks(anchorObject, thisObject);\r\n");
   $nm_saida->saida("        }\r\n");
   $nm_saida->saida("    }\r\n");
   $nm_saida->saida("    function hideNestedGridLinks(objectName, linkType)\r\n");
   $nm_saida->saida("    {\r\n");
   $nm_saida->saida("        let thisObject = document.getElementById(objectName);\r\n");
   $nm_saida->saida("        if ('a' == linkType) {\r\n");
   $nm_saida->saida("            timeoutIndex = setTimeout(function() { thisObject.style.display = 'none'; }, 200);\r\n");
   $nm_saida->saida("            return timeoutIndex;\r\n");
   $nm_saida->saida("        } else {\r\n");
   $nm_saida->saida("            thisObject.style.display = 'none';\r\n");
   $nm_saida->saida("            return null;\r\n");
   $nm_saida->saida("        }\r\n");
   $nm_saida->saida("    }\r\n");
   $nm_saida->saida("    function positionNestedGridLinks(anchorObject, menuElement) {\r\n");
   $nm_saida->saida("        FloatingUIDOM.computePosition(anchorObject, menuElement, {\r\n");
   $nm_saida->saida("          placement: 'bottom-start',\r\n");
   $nm_saida->saida("          middleware: [FloatingUIDOM.flip(), FloatingUIDOM.shift(), FloatingUIDOM.size({\r\n");
   $nm_saida->saida("            apply({availableWidth, availableHeight, elements}) {\r\n");
   $nm_saida->saida("              Object.assign(elements.floating.style, {\r\n");
   $nm_saida->saida("                maxWidth: availableWidth + 'px',\r\n");
   $nm_saida->saida("                maxHeight: availableHeight + 'px',\r\n");
   $nm_saida->saida("                overflow: 'auto'\r\n");
   $nm_saida->saida("              });\r\n");
   $nm_saida->saida("            }\r\n");
   $nm_saida->saida("          })],\r\n");
   $nm_saida->saida("        }).then(({x, y}) => {\r\n");
   $nm_saida->saida("          Object.assign(menuElement.style, {\r\n");
   $nm_saida->saida("            left: x + 'px',\r\n");
   $nm_saida->saida("            top: y + 'px',\r\n");
   $nm_saida->saida("          });\r\n");
   $nm_saida->saida("        });\r\n");
   $nm_saida->saida("    }\r\n");
